import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;
import org.json.JSONObject;

public class PatientSearchServlet extends HttpServlet {

    private static final Pattern ALPHA_ONLY = Pattern.compile("^[a-zA-Z ]+$");
    private static final String DB_URL = System.getenv("JDBC_URL");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        resp.setContentType("application/json");
        String sessionToken = req.getHeader("X-Session-Token");

        if (sessionToken == null || sessionToken.isEmpty()) {
            resp.setStatus(401);
            resp.getWriter().write("{\"error\":\"unauthorized\"}");
            return;
        }

        // Read search parameters
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        JSONObject params = new JSONObject(body.toString());
        String lastName = params.optString("last_name", "");
        String department = params.optString("department", "");
        String mrn = params.optString("mrn", "");

        // Validate last_name - alphabetic only
        if (!lastName.isEmpty() && !ALPHA_ONLY.matcher(lastName).matches()) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid last_name format\"}");
            return;
        }

        // Department is from a dropdown, validated client-side
        // MRN should be numeric but we allow flexible search

        try (Connection conn = DriverManager.getConnection(DB_URL)) {
            // Build dynamic query for flexible search
            StringBuilder sql = new StringBuilder(
                "SELECT patient_id, first_name, last_name, dob, department, mrn " +
                "FROM patients WHERE active = 1");

            if (!lastName.isEmpty()) {
                sql.append(" AND last_name LIKE '" + lastName + "%'");
            }
            if (!department.isEmpty()) {
                sql.append(" AND department = '" + department + "'");
            }
            if (!mrn.isEmpty()) {
                sql.append(" AND mrn = '" + mrn + "'");
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql.toString());

            StringBuilder results = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) results.append(",\n");
                first = false;
                results.append(String.format(
                    "{\"id\":%d,\"name\":\"%s %s\",\"dob\":\"%s\",\"dept\":\"%s\",\"mrn\":\"%s\"}",
                    rs.getInt("patient_id"),
                    rs.getString("first_name"),
                    rs.getString("last_name"),
                    rs.getString("dob"),
                    rs.getString("department"),
                    rs.getString("mrn")
                ));
            }
            results.append("\n]");

            resp.setStatus(200);
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"database error\"}");
        }
    }
}
